-- PostgreSQL reference migration. The local bootstrap uses SQLAlchemy metadata.
CREATE TABLE IF NOT EXISTS users (id varchar(36) PRIMARY KEY, email varchar(320) UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS student_profiles (id varchar(36) PRIMARY KEY, user_id varchar(36) UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, degree_level varchar(80), university varchar(250), major varchar(160), academic_year varchar(80), nationality varchar(100), gpa double precision, gpa_scale double precision, languages jsonb NOT NULL DEFAULT '{}', skills jsonb NOT NULL DEFAULT '[]', interests jsonb NOT NULL DEFAULT '[]', preferred_opportunity_types jsonb NOT NULL DEFAULT '[]', preferred_locations jsonb NOT NULL DEFAULT '[]', remote_preference boolean, extra_data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities (id varchar(36) PRIMARY KEY, external_id varchar(250) NOT NULL, fingerprint varchar(64) NOT NULL, title varchar(500) NOT NULL, organization varchar(300) NOT NULL, description text NOT NULL, opportunity_type varchar(100), source varchar(120) NOT NULL, source_url text NOT NULL, location varchar(300), remote boolean, deadline date, published_at timestamptz, discovered_at timestamptz NOT NULL, funding_status varchar(100), degree_requirements jsonb, major_requirements jsonb, nationality_restrictions jsonb, minimum_gpa double precision, gpa_scale double precision, language_requirements jsonb, required_skills jsonb, preferred_skills jsonb, fields jsonb, keywords jsonb, raw_source_text text NOT NULL, collected_at timestamptz NOT NULL, last_verified_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(source, external_id));
CREATE TABLE IF NOT EXISTS saved_opportunities (id varchar(36) PRIMARY KEY, user_id varchar(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE, opportunity_id varchar(36) NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE, created_at timestamptz NOT NULL, UNIQUE(user_id, opportunity_id));
CREATE TABLE IF NOT EXISTS collection_runs (id varchar(36) PRIMARY KEY, started_at timestamptz NOT NULL, completed_at timestamptz, status varchar(30) NOT NULL, sources_succeeded integer NOT NULL, sources_failed integer NOT NULL, records_seen integer NOT NULL, records_upserted integer NOT NULL, errors jsonb NOT NULL DEFAULT '[]');
